public class Solution {
    public int[] solve(int A) {
        int[] primeArray = new int[A + 1];
        List<Integer> list = new ArrayList<>();
        primeArray[0] = 1;
        primeArray[1] = 1;
        for (int i = 2; i <= A; i++) {
            if (primeArray[i] != 1 && isPrimeNumber(i)) {
                primeArray[i] = 0;
                list.add(i);
            }
            for (int j = 2 * i; j <= A; j = j + i) {
                primeArray[j] = 1;   // mark multiples composite (was primeArray[i] — a bug)
            }
        }
        int[] res = new int[list.size()];
        int index = 0;
        for (int x : list) {
            res[index] = x;
            index++;
        }
        return res;
    }

    public boolean isPrimeNumber(int A) {
        int count = 0;
        for (int i = 1; i <= Math.sqrt(A); i++) {
            if (A % i == 0) {
                count++; // First factor
                if (i != A / i) {
                    // Pair factor
                    count++;
                }
            }
        }
        if (count == 2) {
            return true;
        }
        return false;
    }
}

