public class Solution {
    public int[] primesum(int A) {
        if(A == 4) return new int[]{2,2};
        for(int i = 3; i <= A/2; i = i+2){
            if(isPrimeNumber(i) && isPrimeNumber(A-i)){
                return new int[]{i, A-i};
            }
        }
        return null;
    }

    public boolean isPrimeNumber(int A) {
        int count = 0;
        for (int i = 1; i <= Math.sqrt(A); i++) {
            if (A % i == 0) {
                count++; // First factor
                if (i != A / i) {
                    // Pair factor
                    count++;
                }
            }
        }
        if (count == 2) {
            return true;
        }
        return false;
    }
}

public class Solution {
    public int[] solve(int[] A) {
        int max = 0;
        for (int x : A) max = Math.max(max, x);
        int[] divCount = new int[max + 1];
        for (int d = 1; d <= max; d++) {
            for (int j = d; j <= max; j += d) {
                divCount[j]++;
            }
        }
        int[] res = new int[A.length];
        for (int i = 0; i < A.length; i++) {
            res[i] = divCount[A[i]];
        }
        return res;
    }
}

public class Solution {
    public int solve(int A) {
        int[] cnt = new int[A + 1];
        for (int i = 2; i <= A; i++) {
            if (cnt[i] == 0) {
                for (int j = i; j <= A; j += i) {
                    cnt[j]++;
                }
            }
        }
        int ans = 0;
        for (int x = 1; x <= A; x++) {
            if (cnt[x] == 2) {
                ans++;
            }
        }
        return ans;
    }
}
